import{_ as a,o as n,c as t,a0 as s}from"./chunks/framework.BYCjvD8D.js";const p=JSON.parse('{"title":"Canvas screenshots and future vision-based NEAT","description":"","frontmatter":{},"headers":[],"relativePath":"canvas-vision.md","filePath":"canvas-vision.md"}'),i={name:"canvas-vision.md"};function r(o,e,l,c,d,u){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="canvas-screenshots-and-future-vision-based-neat" tabindex="-1">Canvas screenshots and future vision-based NEAT <a class="header-anchor" href="#canvas-screenshots-and-future-vision-based-neat" aria-label="Permalink to &quot;Canvas screenshots and future vision-based NEAT&quot;">​</a></h1><p>The game captures its <strong>own HTML Canvas</strong>. There are no Playwright screenshots, Python services, or server APIs involved in capture.</p><h2 id="what-the-buttons-do" tabindex="-1">What the buttons do <a class="header-anchor" href="#what-the-buttons-do" aria-label="Permalink to &quot;What the buttons do&quot;">​</a></h2><ul><li><strong>Capture PNG:</strong> <code>HTMLCanvasElement.toBlob(&#39;image/png&#39;)</code> encodes the currently visible game, including overlays.</li><li><strong>Sample pixels:</strong> copies the clean game frame into a 64×36 in-memory Canvas using <code>drawImage()</code>, reads its <code>ImageData</code> with <code>getImageData()</code>, and produces 2,304 grayscale numbers.</li><li><strong>Clean PNG:</strong> saves the separately drawn clean game frame, captured before the diagnostic sensor grid and heads-up display.</li><li><strong>Pixels JSON:</strong> exports the sampled floating-point values and dimensions for inspecting/teaching.</li></ul><p>Only browser-native APIs are used. Downloading requires an explicit click.</p><h2 id="turning-pixels-into-numbers" tabindex="-1">Turning pixels into numbers <a class="header-anchor" href="#turning-pixels-into-numbers" aria-label="Permalink to &quot;Turning pixels into numbers&quot;">​</a></h2><p>Every image pixel contains red (R), green (G), blue (B) and alpha (A), generally each from 0 to 255. Our simple grayscale value is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L = (0.2126 × R + 0.7152 × G + 0.0722 × B) / 255</span></span></code></pre></div><p>Where <code>L</code> is brightness between 0 and 1. The 64×36 image becomes a one-dimensional array of 2,304 numbers, ready to be consumed by a future pixel-sensing neural model. The UI shows this tiny image with enlarged pixels and gives you the mean brightness.</p><h2 id="what-neat-currently-sees" tabindex="-1">What NEAT currently sees <a class="header-anchor" href="#what-neat-currently-sees" aria-label="Permalink to &quot;What NEAT currently sees&quot;">​</a></h2><p>The existing champion policy uses <strong>169 structured game sensors</strong> (a 13×13 collision/enemy grid), not the new 2,304-pixel observation. Sampling is implemented for inspection and export, <strong>not yet wired into training</strong>. The goal is to keep a verified reference implementation while we build the more difficult vision experiment.</p><h2 id="webgpu-later" tabindex="-1">WebGPU later <a class="header-anchor" href="#webgpu-later" aria-label="Permalink to &quot;WebGPU later&quot;">​</a></h2><p>The Canvas capture step does not require WebGPU. A future WebGPU compute implementation could batch neural forward passes in WebGPU Shading Language (WGSL), while evolutionary mutations and speciation stay on the CPU initially.</p><p>Don&#39;t call <code>toBlob()</code> on every simulation tick: compressing thousands of PNGs is not a practical training pipeline. Feed compact arrays (or GPU textures/buffers) directly to the model, benchmark GPU transfers, and compare against the current CPU Web Worker baseline. Our current GPU feature is Three.js <strong>rendering</strong>, not acceleration of NEAT itself.</p>',14)])])}const g=a(i,[["render",r]]);export{p as __pageData,g as default};
